/**
 * @file build/gen-i18n-content.mjs
 * 文件职责：由 extension/i18n.js 生成内容脚本专用的 extension/i18n-content.js——
 *   运行时逻辑原样保留，DICTS 只留网页侧脚本实际用到的命名空间，免得每个网页都
 *   解析设置页/引导页的全部文案。
 * 主要内容：contentSideFiles 由 manifest 推导网页侧脚本清单；collectNamespaces 扫描其中出现的
 *   词典键字面量并取首段命名空间；buildContentI18n 组装生成物；
 *   脚本入口把生成结果写回源树（// Generated by 头豁免 R7 文件头门禁）。
 * 模块边界：构建期代码生成，写 extension/i18n-content.js；单元测试断言源树无漂移。
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at https://mozilla.org/MPL/2.0/.

 */
import {readFileSync, writeFileSync} from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import vm from 'node:vm';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const EXTENSION_DIR = path.join(repoRoot, 'roamcat-0.0.1', 'extension');

/** 不在 manifest 静态清单里、由 background 经 chrome.scripting 注入网页的脚本。 */
const DYNAMIC_CONTENT_FILES = Object.freeze(['floating-pet-helpers.js', 'floating-pet-styles.js', 'floating-pet-svg.js', 'floating-pet-quote-bubble.js', 'floating-pet-summary.js', 'floating-pet.js', 'video-subtitles.js', 'auto-start.js']);

/** 在网页里运行、经 RoamCatI18n 取文案的脚本：manifest 全部静态 content_scripts + 动态注入脚本。 */
export function contentSideFiles() {
  const manifest = JSON.parse(readFileSync(path.join(EXTENSION_DIR, 'manifest.json'), 'utf8'));
  const statics = (manifest.content_scripts || []).flatMap(entry => entry.js || []);
  return [...new Set([...statics, ...DYNAMIC_CONTENT_FILES])].filter(name => name !== 'i18n-content.js');
}

const DICTS_START = '  const DICTS = {';
const DICTS_END = '\n  const listeners = new Set();';
const KEY_LITERAL = /['"`]([a-zA-Z]+(?:\.[\w-]+)+)['"`]/gu;

/** 以 classic 方式求值 i18n.js，取出完整 DICTS。 */
export function loadDicts(i18nSource) {
  const sandbox = {localStorage: {getItem: () => null, setItem() {}}};
  sandbox.globalThis = sandbox;
  vm.runInNewContext(i18nSource, sandbox, {filename: 'i18n.js'});
  return sandbox.RoamCatI18n.dicts;
}

/**
 * 网页侧脚本里出现的词典键所属命名空间（键的首段）。按整段命名空间保留，
 * 而非逐键保留：拼接/查表得到的键（如 statusFailures、domainName 映射）也在同一段内。
 * @param {Record<string,string>} zh 基准字典
 * @param {string[]} sources 网页侧脚本源码
 */
export function collectNamespaces(zh, sources) {
  const namespaces = new Set();
  for (const source of sources) {
    for (const [, key] of source.matchAll(KEY_LITERAL)) {
      if (Object.hasOwn(zh, key)) namespaces.add(key.split('.')[0]);
    }
  }
  return [...namespaces].sort();
}

/**
 * @param {string} i18nSource extension/i18n.js 源码
 * @param {string[]} contentSources 网页侧脚本源码
 * @returns {string} i18n-content.js 全文
 */
export function buildContentI18n(i18nSource, contentSources) {
  const start = i18nSource.indexOf(DICTS_START);
  const end = i18nSource.indexOf(DICTS_END);
  if (start < 0 || end < 0) throw new Error('i18n.js 中找不到 DICTS 字面量边界');
  const dicts = loadDicts(i18nSource);
  const namespaces = new Set(collectNamespaces(dicts.zh, contentSources));
  const pick = dict => Object.fromEntries(Object.entries(dict).filter(([key]) => namespaces.has(key.split('.')[0])));
  const slim = {zh: pick(dicts.zh), en: pick(dicts.en)};
  return `// Generated by build/gen-i18n-content.mjs from extension/i18n.js (namespaces: ${[...namespaces].join(', ')}); do not edit by hand.\n`
    + i18nSource.slice(0, start)
    + `  const DICTS = ${JSON.stringify(slim, null, 1).replace(/\n/gu, '\n  ')};\n`
    + i18nSource.slice(end);
}

/** 读取源树并生成。 */
export function generateFromTree() {
  const read = name => readFileSync(path.join(EXTENSION_DIR, name), 'utf8');
  return buildContentI18n(read('i18n.js'), contentSideFiles().map(read));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(path.join(EXTENSION_DIR, 'i18n-content.js'), generateFromTree());
}
